<script setup>
import {ref,computed,inject,onMounted} from 'vue'
import {phases,choices} from '../services/repository'
import DefinitionDialog from '../components/DefinitionDialog.vue'
const repo=inject('repository'),domain=ref(),error=ref(''),loading=ref(true),selected=ref(),open=ref(false),version=ref(0)
const fresh=()=>({search:'',phase:'all',goal:'all',level:'all',status:'all'}),f=ref(fresh())
const state=id=>{version.value;return domain.value.workflows.status(id)}
const labels={enabled:'已启用',disabled:'未启用',unsupported:'数据源不支持'},colors={enabled:'success',disabled:'secondary',unsupported:'warning'}
const goals=computed(()=>[...new Set(domain.value?.rules.map(r=>r.workflow.goal)||[])])
const rows=computed(()=>domain.value?.rules.filter(r=>{const w=r.workflow;return [r.name,r.id,r.category].join(' ').toLowerCase().includes(String(f.value.search||'').trim().toLowerCase())&&(f.value.phase==='all'||w.phase===f.value.phase)&&(f.value.goal==='all'||w.goal===f.value.goal)&&(f.value.level==='all'||w.levels.includes(f.value.level))&&(f.value.status==='all'||state(r.id)===f.value.status)})||[])
async function load(){loading.value=true;try{domain.value=await repo.getDomain();error.value=''}catch(e){error.value=e.message}finally{loading.value=false}}
function select(r){selected.value=r;open.value=true}
onMounted(load)
</script>
<template><div class="page-heading"><div><h1>规则配置</h1><p>定义随代码发布，仅开放业务允许的运行参数。</p></div><VChip color="primary" variant="tonal" label>{{domain?.rules.length||0}} 项发布定义</VChip></div><VAlert v-if="error" type="error">{{error}}<VBtn @click="load">重试</VBtn></VAlert><VProgressLinear v-if="loading" indeterminate/>
<VCard class="mb-6"><div class="toolbar"><VTextField v-model="f.search" class="toolbar-search" placeholder="搜索规则名称、编号或分类" prepend-inner-icon="tabler-search" aria-label="搜索规则" clearable/><VBtn variant="text" color="secondary" prepend-icon="tabler-refresh" @click="f=fresh()">重置筛选</VBtn></div><div class="filters"><div class="field"><label>监管阶段</label><VSelect v-model="f.phase" :items="[{value:'all',title:'全部阶段'},...choices(phases)]"/></div><div class="field"><label>决策目标</label><VSelect v-model="f.goal" :items="[{value:'all',title:'全部目标'},...goals.map(g=>({value:g,title:g}))]"/></div><div class="field"><label>适用手术等级</label><VSelect v-model="f.level" :items="[{value:'all',title:'全部等级'},...['I','II','III','IV'].map(g=>({value:g,title:g+' 级手术'}))]"/></div><div class="field"><label>运行状态</label><VSelect v-model="f.status" :items="[{value:'all',title:'全部状态'},...choices(labels)]"/></div></div></VCard>
<div class="result-count">{{rows.length}} / {{domain?.rules.length||0}} 条规则</div><div class="catalog-grid"><VCard v-for="r in rows" :key="r.id" class="definition-card" tabindex="0" role="button" :aria-label="'配置'+r.name" @click="select(r)" @keydown.enter="select(r)" @keydown.space.prevent="select(r)"><VCardText><div class="card-kicker"><span>{{r.workflow.goal}}</span><VChip :color="colors[state(r.id)]" size="small" variant="tonal" label>{{labels[state(r.id)]}}</VChip></div><h2>{{r.name}}</h2><p class="definition-desc">{{r.threshold}}</p><div class="definition-meta"><span>{{phases[r.workflow.phase]}}</span><span>{{r.workflow.levels.join(' / ')}} 级</span><span>{{({event:'事件触发',deadline:'截止时点',stream:'连续窗口'})[r.workflow.mode]}}</span></div><div class="card-end"><code>{{r.id}}</code><span>查看配置 <VIcon icon="tabler-chevron-right" size="16"/></span></div></VCardText></VCard></div><VCard v-if="!loading&&!rows.length" class="empty"><h3>没有符合分类条件的规则</h3><VBtn variant="text" @click="f=fresh()">清除筛选</VBtn></VCard><DefinitionDialog v-model="open" kind="risk" :definition="selected" :domain="domain" @saved="version++"/></template>
